CREATE VIEW v23522 AS SELECT *, CONV(29223372036854775809, -10, 16) AS x1, ST_EQUALS(ST_GEOMFROMTEXT('MULTIPOINT(2 0, 4 0)'), SEC_TO_TIME(x5.x2)) AS x2 FROM v22630 AS x5 JOIN v23486 AS x4 JOIN x6 USING (x7, x8) ON x5.x2 = x5.x2 WHERE x4.v23487 IN ('Current_tls_ca', 'Current_tls_capath', 'Current_tls_cert', 'Current_tls_key', 'Current_tls_version', 'Current_tls_cipher', 'Current_tls_ciphersuites', 'Current_tls_crl', 'Current_tls_crlpath') AND x5.x2 <> 'gizmo'